fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let tab = [0, 49, 90, 117, 127, 117, 90, 49, 0, -49, -90, -117, -127, -117, -90, -49];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cycle: i32 = 140;
    let phase: i32 = t % cycle;
    let shot: i32 = t / cycle;
    let cx: i32 = w / 4 + hash(shot * 17 + 3) % (w / 2);
    let cy: i32 = h / 4;
    host::display::clear(0x000008);
    if phase < 50 {
        let y: i32 = h - phase * (h - cy) / 50;
        host::display::fill_rect(cx - 1, y, 2, 6, 0xffffc0);
    } else {
        let age: i32 = phase - 50;
        let mut k: i32 = 0;
        while k < 16 {
            let px: i32 = cx + tab[k] * age / 96;
            let py: i32 = cy + tab[(k + 4) & 15] * age / 96 + age * age / 40;
            let c: i32 = if age < 30 { 0xffe060 } else if age < 60 { 0xff6030 } else { 0x502018 };
            host::display::fill_rect(px, py, 2, 2, c);
            k = k + 1;
        }
    }
    host::display::present();
}
